#import "SLLibraryViewController.h"
#import "SLStore.h"
#import "SLTitleViewController.h"
#import "SLReaderViewController.h"
#import "SLDownloadManager.h"
#import "SLTheme.h"
#import "SLImageLoader.h"
@implementation SLLibraryViewController
- (id)initWithKind:(SLLibraryKind)kind { if((self=[super initWithStyle:UITableViewStylePlain])){_kind=kind;_rows=[[NSMutableArray alloc]init];NSArray *names=[NSArray arrayWithObjects:@"Избранное",@"Закладки",@"Недавние",@"Загрузки",nil];self.title=[names objectAtIndex:kind];}return self; }
- (void)viewWillAppear:(BOOL)animated { [super viewWillAppear:animated];self.tableView.backgroundColor=[SLTheme backgroundColor];[_rows removeAllObjects];NSString *key=_kind==SLLibraryFavorites?@"SLFavorites":(_kind==SLLibraryBookmarks?@"SLBookmarks":@"SLHistory");if(_kind==SLLibraryDownloads)[_rows addObjectsFromArray:[[SLDownloadManager shared]downloads]];else [_rows addObjectsFromArray:[SLStore array:key]];[self.tableView reloadData]; }
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return [_rows count];}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)p {static NSString *ident=@"SLLibraryCell";UITableViewCell *c=[t dequeueReusableCellWithIdentifier:ident];if(!c)c=[[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:ident]autorelease];NSDictionary *d=[_rows objectAtIndex:p.row];NSDictionary *titleInfo=[d objectForKey:@"titleInfo"];NSDictionary *ch=[d objectForKey:@"_lastChapter"]?:[d objectForKey:@"chapter"];c.textLabel.text=[d objectForKey:@"rus_name"]?:[titleInfo objectForKey:@"rus_name"]?:[titleInfo objectForKey:@"_display"]?:[d objectForKey:@"title"]?:[d objectForKey:@"name"]?:[d objectForKey:@"slug"]?:@"Тайтл";if(_kind==SLLibraryBookmarks)c.detailTextLabel.text=[NSString stringWithFormat:@"Том %@ · Глава %@ · стр. %@",[d objectForKey:@"volume"]?:@"?",[d objectForKey:@"number"]?:@"?",[d objectForKey:@"page"]?:@"1"];else if(ch)c.detailTextLabel.text=[NSString stringWithFormat:@"Том %@ · Глава %@%@",[ch objectForKey:@"volume"]?:@"?",[ch objectForKey:@"number"]?:@"?",_kind==SLLibraryHistory?[NSString stringWithFormat:@" · стр. %@",[NSNumber numberWithInteger:[[d objectForKey:@"_lastPage"]integerValue]+1]]:@""];else c.detailTextLabel.text=[d objectForKey:@"eng_name"];NSDictionary *cover=[d objectForKey:@"cover"]?:[titleInfo objectForKey:@"cover"];NSString *coverURL=[cover isKindOfClass:[NSDictionary class]]?([cover objectForKey:@"thumbnail"]?:[cover objectForKey:@"default"]):nil;c.imageView.image=nil;c.imageView.accessibilityIdentifier=coverURL;if([coverURL length])[[SLImageLoader shared]load:coverURL site:[[d objectForKey:@"site"]integerValue] completion:^(UIImage *image){if([c.imageView.accessibilityIdentifier isEqualToString:coverURL]){c.imageView.image=image;[c setNeedsLayout];}}];c.textLabel.textColor=[SLTheme textColor];c.detailTextLabel.textColor=[SLTheme textColor];c.backgroundColor=[SLTheme backgroundColor];c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return c; }
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)p {[t deselectRowAtIndexPath:p animated:YES];NSDictionary *d=[_rows objectAtIndex:p.row];if(_kind==SLLibraryBookmarks){NSString *slug=[d objectForKey:@"slug"];NSDictionary *ch=[NSDictionary dictionaryWithObjectsAndKeys:[d objectForKey:@"chapterId"]?:@"0",@"id",[d objectForKey:@"volume"]?:@"0",@"volume",[d objectForKey:@"number"]?:@"0",@"number",[d objectForKey:@"site"]?:@2,@"site",[d objectForKey:@"branchIds"]?:[NSArray array],@"branchIds",[d objectForKey:@"page"]?:@0,@"_startPage",nil];SLReaderViewController *v=[[[SLReaderViewController alloc]initWithSlug:slug chapter:ch titleInfo:[d objectForKey:@"titleInfo"]]autorelease];[self.navigationController pushViewController:v animated:YES];}else if(_kind==SLLibraryHistory&&[d objectForKey:@"_lastChapter"]){NSMutableDictionary *ch=[NSMutableDictionary dictionaryWithDictionary:[d objectForKey:@"_lastChapter"]];[ch setObject:[d objectForKey:@"_lastPage"]?:@0 forKey:@"_startPage"];SLReaderViewController *v=[[[SLReaderViewController alloc]initWithSlug:([d objectForKey:@"slug_url"]?:[d objectForKey:@"slug"]) chapter:ch titleInfo:d]autorelease];[self.navigationController pushViewController:v animated:YES];}else if(_kind==SLLibraryDownloads){NSDictionary *ch=[d objectForKey:@"chapter"];NSDictionary *titleInfo=[NSDictionary dictionaryWithObjectsAndKeys:[d objectForKey:@"title"]?:[d objectForKey:@"slug"],@"rus_name",[d objectForKey:@"slug"],@"slug_url",[d objectForKey:@"slug"],@"slug",nil];SLReaderViewController *v=[[[SLReaderViewController alloc]initWithSlug:[d objectForKey:@"slug"] chapter:ch titleInfo:titleInfo]autorelease];[self.navigationController pushViewController:v animated:YES];}else{SLTitleViewController *v=[[[SLTitleViewController alloc]initWithTitle:d]autorelease];[self.navigationController pushViewController:v animated:YES];}}
- (void)tableView:(UITableView *)t commitEditingStyle:(UITableViewCellEditingStyle)style forRowAtIndexPath:(NSIndexPath *)p {if(style!=UITableViewCellEditingStyleDelete)return;NSDictionary *d=[_rows objectAtIndex:p.row];if(_kind==SLLibraryFavorites){[SLStore markDeleted:@"favorite" record:d];NSMutableArray *a=[NSMutableArray arrayWithArray:[SLStore array:@"SLFavorites"]];[a removeObject:d];[SLStore saveArray:a key:@"SLFavorites"];}else if(_kind==SLLibraryBookmarks){[SLStore markDeleted:@"bookmark" record:d];NSMutableArray *a=[NSMutableArray arrayWithArray:[SLStore array:@"SLBookmarks"]];[a removeObject:d];[SLStore saveArray:a key:@"SLBookmarks"];}else if(_kind==SLLibraryHistory){[SLStore markDeleted:@"recent" record:d];NSMutableArray *a=[NSMutableArray arrayWithArray:[SLStore array:@"SLHistory"]];[a removeObject:d];[SLStore saveArray:a key:@"SLHistory"];}else{NSMutableArray *a=[NSMutableArray arrayWithArray:[[SLDownloadManager shared]downloads]];[[NSFileManager defaultManager]removeItemAtPath:[d objectForKey:@"path"] error:nil];[a removeObject:d];[SLStore saveArray:a key:@"SLDownloaded"];}[_rows removeObjectAtIndex:p.row];[t deleteRowsAtIndexPaths:[NSArray arrayWithObject:p] withRowAnimation:UITableViewRowAnimationFade];}
- (void)dealloc{[_rows release];[super dealloc];}
@end
